using Microsoft.EntityFrameworkCore;using Microsoft.EntityFrameworkCore.Metadata.Builders;using Qms.Domain.MasterBatchRecords;namespace Qms.Infrastructure.Persistence.Configurations;public sealed class MasterBatchRecordConfiguration:IEntityTypeConfiguration<MasterBatchRecord>{public void Configure(EntityTypeBuilder<MasterBatchRecord>b){b.ToTable("master_batch_record","mbr");b.HasKey(x=>x.Id);foreach(var p in new[]{nameof(MasterBatchRecord.ProductCode),nameof(MasterBatchRecord.DosageFormCode),nameof(MasterBatchRecord.BatchUnitCode),nameof(MasterBatchRecord.SiteCode),nameof(MasterBatchRecord.LineCode),nameof(MasterBatchRecord.DocumentVersion)})b.Property(p).HasMaxLength(80).IsRequired();foreach(var p in new[]{nameof(MasterBatchRecord.ProductName),nameof(MasterBatchRecord.DosageFormName),nameof(MasterBatchRecord.BatchUnitName),nameof(MasterBatchRecord.SiteName),nameof(MasterBatchRecord.LineName),nameof(MasterBatchRecord.Strength)})b.Property(p).HasMaxLength(240).IsRequired();b.Property(x=>x.ChangeReason).HasMaxLength(3000).IsRequired();b.Property(x=>x.Author).HasMaxLength(200).IsRequired();b.Property(x=>x.Reviewer).HasMaxLength(200).IsRequired();b.Property(x=>x.Approver).HasMaxLength(200).IsRequired();b.Property(x=>x.BatchSize).HasPrecision(18,4);b.Property(x=>x.Status).HasConversion<string>().HasMaxLength(40);b.Property(x=>x.Version).IsConcurrencyToken();b.HasIndex(x=>x.QualityRecordId).IsUnique();b.HasIndex(x=>new{x.ProductCode,x.SiteCode,x.Status});b.HasOne<Qms.Domain.QualityRecords.QualityRecord>().WithMany().HasForeignKey(x=>x.QualityRecordId).OnDelete(DeleteBehavior.Restrict);b.HasOne<MasterBatchRecord>().WithMany().HasForeignKey(x=>x.PreviousVersionId).OnDelete(DeleteBehavior.Restrict);b.HasOne<Qms.Infrastructure.Identity.ApplicationUser>().WithMany().HasForeignKey(x=>x.AuthorUserId).OnDelete(DeleteBehavior.Restrict);b.HasOne<Qms.Infrastructure.Identity.ApplicationUser>().WithMany().HasForeignKey(x=>x.ReviewerUserId).OnDelete(DeleteBehavior.Restrict);b.HasOne<Qms.Infrastructure.Identity.ApplicationUser>().WithMany().HasForeignKey(x=>x.ApproverUserId).OnDelete(DeleteBehavior.Restrict);b.HasMany(x=>x.Steps).WithOne().HasForeignKey(x=>x.MasterBatchRecordId).OnDelete(DeleteBehavior.Cascade);b.Navigation(x=>x.Steps).UsePropertyAccessMode(PropertyAccessMode.Field);}}
public sealed class MasterBatchStepConfiguration:IEntityTypeConfiguration<MasterBatchStep>{public void Configure(EntityTypeBuilder<MasterBatchStep>b){b.ToTable("step","mbr");b.HasKey(x=>x.Id);b.Property(x=>x.PhaseCode).HasMaxLength(80).IsRequired();b.Property(x=>x.PhaseName).HasMaxLength(160).IsRequired();b.Property(x=>x.Instruction).HasMaxLength(6000).IsRequired();b.Property(x=>x.MaterialOrEquipmentReference).HasMaxLength(1000);b.Property(x=>x.Parameter).HasMaxLength(240);b.Property(x=>x.UnitCode).HasMaxLength(80);b.Property(x=>x.UnitName).HasMaxLength(160);b.Property(x=>x.LowerLimit).HasPrecision(18,4);b.Property(x=>x.UpperLimit).HasPrecision(18,4);b.HasIndex(x=>new{x.MasterBatchRecordId,x.Order}).IsUnique();}}
public sealed class MbrLookupDefinitionConfiguration:IEntityTypeConfiguration<MbrLookupDefinition>{public void Configure(EntityTypeBuilder<MbrLookupDefinition>b){b.ToTable("lookup_definition","mbr");b.HasKey(x=>x.Id);b.Property(x=>x.Category).HasMaxLength(40).IsRequired();b.Property(x=>x.Code).HasMaxLength(80).IsRequired();b.Property(x=>x.Name).HasMaxLength(160).IsRequired();b.HasIndex(x=>new{x.Category,x.Code}).IsUnique();}}
